mapper.select:
SELECT id, token_hash, user_id, identity_id, user_agent, client_ip, created_at, expires_at, revoked_at
FROM user_session
WHERE token_hash = #{tokenHash}

mapper.update:
UPDATE user_session
SET revoked_at = #{revokedAt}
WHERE id = #{id} AND revoked_at IS NULL

UPDATE user_session
SET revoked_at = #{revokedAt}
WHERE user_id = #{userId} AND revoked_at IS NULL
